import * as React from "react";
import { connect } from "react-redux";
import { Dispatch } from "redux";
import { toggleSidebar } from "../../store";
import { SemanticICONS, Segment, Header, Container, Label, Menu, Icon } from "semantic-ui-react";
import { MenuProps } from "../Menu";

interface HeaderMenuProps extends MenuProps {
  dispatch?: Dispatch<any>;
  inverted?: boolean;
}

export const HeaderMenu = ({ items, pathname, Link, inverted, dispatch }: HeaderMenuProps) =>
  <Segment className="masthead" basic>
    <Menu size="large" inverted={inverted} secondary>
      <Menu.Item as="a" className="mobile only" icon="sidebar" onClick={() => dispatch && dispatch(toggleSidebar())} />
      <Menu.Item fitted="vertically" className="mobile hidden logo-item">
      <div className="logo">
        <img src="https://www.gravatar.com/avatar/13944326b651e8b820a4fd6a56611f2f" />
      </div>
      </Menu.Item>
      <Menu.Item className="logo-item">
      <div className="type">
        <Header as="h2">
        Edward J. Schwartz
        </Header>
        <Header as="h2" sub>
        Computer Security Researcher
        </Header>
      </div>
      </Menu.Item>
      <Menu.Menu position="right">
      {items.map((item) => {
        const active = (item.exact) ? pathname === item.path : pathname.startsWith(item.path);
        return <Menu.Item
          as={Link}
          className="mobile hidden"
          name={item.name}
          to={item.path}
          key={item.path}
          active={active}
        >
          <Icon name={item.icon as SemanticICONS} color="grey" /> {item.name}
        </Menu.Item>;
      })}
      </Menu.Menu>
    </Menu>

    <style jsx>{`
      .logo {
        border-radius: 65% 75%;
        border: 1px solid #eee;
        display: inline-block;
        height: 60px;
        width: 60px;
        overflow: hidden;
        transition: all 0.5s;
      
        img {
          width: 100%;
        }
      }

      :global(.logo-item) {
        transition: all 0.5s !important;
        @media only screen and (max-width: 767px) {
          padding: 0.2em !important;
          margin: 0 !important;
        }
      }

      .type {
        text-align: left;

        :global(h2) {
          margin: 0 !important;
        }
      }
    `}</style>
  </Segment>;

export default connect()(HeaderMenu);
